#!/usr/bin/env bash
# v2: on/off manage ALL kernel AWG customers; no customer data or keys embedded.
set -Eeuo pipefail
umask 077
if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
  cat <<'HELP'
Run as root on a relay built by this repository, after restoring LucX DB.
Install and enable ALL AWG customers: bash ru-bypass.sh install
Update command without enabling: bash ru-bypass.sh setup
Enable: ru-bypass on     Disable: ru-bypass off     Check: ru-bypass status
New AWG customers in 10.8.0.0/24 are automatic while ON; no name list needed.
Also supported: bash ru-bypass.sh on|off|status
IPv4 IP-only bypass. No DNS/VLESS changes, boot persistence or automatic list updates.
HELP
  exit 0
fi
[[ "$(uname -s)" == Linux && "$EUID" -eq 0 ]] || { echo 'Run as root on the Linux relay.' >&2; exit 1; }
for dependency in python3 nft ip awg systemctl curl; do
  command -v "$dependency" >/dev/null || { echo "Missing $dependency. Restore AWG infrastructure first." >&2; exit 1; }
done
PYTHONDONTWRITEBYTECODE=1 /usr/bin/python3 - "$@" <<'RU_BYPASS_PYTHON'
FILES={'ru_bypass_common.py': '"""Runtime Russian IPv4 bypass for all kernel AWG sources in the customer subnet."""\nimport json\nimport subprocess\nfrom pathlib import Path\n\nVERSION=2\nTABLE=\'awg_ru3_trial\'\nROUTE_TABLE=\'51833\'\nMARK=\'0x52000000\'\nMASK=\'0xff000000\'\nSOURCE=\'10.8.0.0/24\'\nPREFIX=\'awg-ru3-trial:\'\nPRIORITIES=(10021,10022)\n\ndef output(*args):return subprocess.check_output(args,text=True)\n\ndef rule_signature(rule):\n    value=json.loads(json.dumps(rule))\n    for expr in value.get(\'expr\',[]):\n        if \'counter\' in expr:expr[\'counter\']={}\n    return value\n\ndef rules(document):return [item[\'rule\'] for item in document[\'nftables\'] if \'rule\' in item]\n\ndef anchor(document):\n    candidates=[]\n    for rule in rules(document):\n        if rule.get(\'chain\')!=\'forward_guard\':continue\n        for expr in rule[\'expr\']:\n            match=expr.get(\'match\',{})\n            if match.get(\'op\')==\'!=\' and match.get(\'right\')==\'awg32\' and match.get(\'left\')=={\'meta\':{\'key\':\'oifname\'}}:\n                candidates.append(rule[\'handle\'])\n    assert len(candidates)==1,\'Cannot identify the existing forwarding guard\'\n    return candidates[0]\n\ndef nft_config(cidrs,wan,position):\n    networks=\', \'.join(cidrs)\n    return f\'\'\'table inet {TABLE} {{\n set ru4 {{ type ipv4_addr; flags interval; auto-merge; elements = {{ {networks} }}; }}\n chain classify {{\n  type filter hook prerouting priority mangle; policy accept;\n  iifname "xui-awg1" ip saddr {SOURCE} ct mark & {MASK} == {MARK} counter meta mark set (meta mark & 0x00ffffff) | {MARK} return comment "{PREFIX}restore"\n  iifname "xui-awg1" ip saddr {SOURCE} ct state new ip daddr @ru4 counter ct mark set (ct mark & 0x00ffffff) | {MARK} meta mark set (meta mark & 0x00ffffff) | {MARK} comment "{PREFIX}all"\n }}\n chain postrouting_direct {{\n  type nat hook postrouting priority srcnat - 2; policy accept;\n  oifname "{wan}" ip saddr {SOURCE} ct mark & {MASK} == {MARK} counter masquerade comment "{PREFIX}snat"\n }}\n}}\ninsert rule inet amnezia_legacy_relay forward_guard position {position} iifname "xui-awg1" oifname "{wan}" ip saddr {SOURCE} ct mark & {MASK} == {MARK} ct state {{ new, established, related }} counter accept comment "{PREFIX}allow-out"\ninsert rule inet amnezia_legacy_relay forward_guard position {position} iifname "{wan}" oifname "xui-awg1" ip daddr {SOURCE} ct mark & {MASK} == {MARK} ct state {{ established, related }} counter accept comment "{PREFIX}allow-return"\n\'\'\'\n\ndef routing_commands(wan,gateway):\n    return [\n        [\'ip\',\'-4\',\'route\',\'add\',\'table\',ROUTE_TABLE,gateway+\'/32\',\'dev\',wan,\'scope\',\'link\'],\n        [\'ip\',\'-4\',\'route\',\'add\',\'table\',ROUTE_TABLE,\'default\',\'via\',gateway,\'dev\',wan],\n        [\'ip\',\'-4\',\'rule\',\'add\',\'priority\',str(PRIORITIES[0]),\'from\',SOURCE,\'fwmark\',MARK+\'/\'+MASK,\'table\',ROUTE_TABLE],\n        [\'ip\',\'-4\',\'rule\',\'add\',\'priority\',str(PRIORITIES[1]),\'from\',SOURCE,\'fwmark\',MARK+\'/\'+MASK,\'unreachable\'],\n    ]\n\ndef cleanup_commands(wan,gateway):\n    return [\n        [\'ip\',\'-4\',\'rule\',\'del\',\'priority\',str(PRIORITIES[0]),\'from\',SOURCE,\'fwmark\',MARK+\'/\'+MASK,\'table\',ROUTE_TABLE],\n        [\'ip\',\'-4\',\'rule\',\'del\',\'priority\',str(PRIORITIES[1]),\'from\',SOURCE,\'fwmark\',MARK+\'/\'+MASK,\'unreachable\'],\n        [\'ip\',\'-4\',\'route\',\'del\',\'table\',ROUTE_TABLE,\'default\',\'via\',gateway,\'dev\',wan],\n        [\'ip\',\'-4\',\'route\',\'del\',\'table\',ROUTE_TABLE,gateway+\'/32\',\'dev\',wan,\'scope\',\'link\'],\n    ]\n\ndef nft_cleanup(document,table_exists):\n    commands=[f\'delete rule inet amnezia_legacy_relay forward_guard handle {r["handle"]}\' for r in rules(document) if r.get(\'comment\',\'\').startswith(PREFIX)]\n    if table_exists:commands.append(f\'delete table inet {TABLE}\')\n    return \'\\n\'.join(commands)+\'\\n\' if commands else \'\'\n\ndef verify_resources(state):\n    assert state[\'table\']==TABLE and str(state[\'route_table\'])==ROUTE_TABLE and state[\'mark\']==MARK and state[\'mask\']==MASK,\'Unknown bypass resource allocation\'\n    found=[r for r in json.loads(output(\'ip\',\'-j\',\'-4\',\'rule\')) if r.get(\'priority\') in PRIORITIES]\n    assert len(found)==2 and all(r.get(\'src\')==\'10.8.0.0\' and r.get(\'srclen\')==24 and r.get(\'fwmark\')==MARK and r.get(\'fwmask\')==MASK for r in found),\'Unexpected policy rules\'\n    assert any(str(r.get(\'table\'))==ROUTE_TABLE for r in found) and any(r.get(\'action\')==\'unreachable\' for r in found),\'Incomplete policy rules\'\n    routes=json.loads(output(\'ip\',\'-j\',\'-4\',\'route\',\'show\',\'table\',ROUTE_TABLE))\n    assert len(routes)==2 and all(r.get(\'dev\')==state[\'wan\'] for r in routes),\'Unexpected direct routing table\'\n    assert any(r.get(\'dst\')==\'default\' and r.get(\'gateway\')==state[\'gateway\'] for r in routes)\n    assert any(r.get(\'dst\') in (state[\'gateway\'],state[\'gateway\']+\'/32\') and r.get(\'scope\')==\'link\' for r in routes)\n    guard=json.loads(output(\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\'))\n    owned=[r for r in rules(guard) if r.get(\'comment\',\'\').startswith(PREFIX)]\n    assert sorted(r.get(\'comment\') for r in owned)==[PREFIX+\'allow-out\',PREFIX+\'allow-return\'],\'Unexpected guard exceptions\'\n    return guard\n\ndef subnet_match(rule,field):\n    return any(e.get(\'match\',{}).get(\'left\')=={\'payload\':{\'protocol\':\'ip\',\'field\':field}} and e[\'match\'].get(\'right\')=={\'prefix\':{\'addr\':\'10.8.0.0\',\'len\':24}} for e in rule[\'expr\'])\n\ndef verify_all(root,state):\n    assert state.get(\'mode\')==\'all\' and state.get(\'source_subnet\')==SOURCE,\'Not an all-customer configuration\'\n    assert not (Path(root)/\'rolled-back.json\').exists(),\'Bypass was rolled back\'\n    assert (Path(root)/\'verified.json\').exists(),\'Apply verification missing\'\n    guard=verify_resources(state)\n    table=json.loads(output(\'nft\',\'-j\',\'list\',\'table\',\'inet\',TABLE))\n    owned=rules(table)\n    assert sorted(r.get(\'comment\',\'\') for r in owned)==[PREFIX+\'all\',PREFIX+\'restore\',PREFIX+\'snat\'],\'Unexpected classifier rules\'\n    assert all(subnet_match(r,\'saddr\') for r in owned),\'Classifier is not subnet-wide\'\n    for r in rules(guard):\n        if r.get(\'comment\')==PREFIX+\'allow-out\':assert subnet_match(r,\'saddr\')\n        if r.get(\'comment\')==PREFIX+\'allow-return\':assert subnet_match(r,\'daddr\')\n', 'apply.py': '"""Apply subnet-wide bypass, including atomic migration from the previous selected-peer trial."""\nimport hashlib,ipaddress,json,os,re,sqlite3,subprocess\nfrom datetime import datetime,timezone,timedelta\nfrom pathlib import Path\nfrom ru_bypass_common import *\n\nos.umask(0o077)\nroot=Path(__file__).resolve().parent\nsource=json.loads((root/\'ru-ipv4.json\').read_text())\nsimulation=json.loads((root/\'simulation-report.json\').read_text())\nassert simulation.get(\'mode\')==\'all\' and all(simulation.get(k) for k in [\'all_awg_ru_direct\',\'new_peer_auto\',\'non_ru_foreign\',\'snat_verified\',\'fail_closed_verified\',\'rollback_verified\'])\nassert not (root/\'state.json\').exists(),\'This apply was already attempted\'\nnetworks=[ipaddress.ip_network(n,strict=True) for n in source[\'ipv4_cidrs\']]\nassert 1000<len(networks)<100000 and all(n.version==4 and n.is_global and n.prefixlen>=8 for n in networks)\ndef is_ru(ip):return any(ipaddress.ip_address(ip) in n for n in networks)\nassert is_ru(\'77.88.55.80\') and not is_ru(\'1.1.1.1\')\n\ndef command(args,check=True):\n    result=subprocess.run(args,capture_output=True,text=True)\n    if check and result.returncode:\n        (root/\'last-command-error.txt\').write_text(\' \'.join(args)+\'\\n\'+result.stdout+result.stderr)\n        raise RuntimeError(\'Command failed; see \'+str(root/\'last-command-error.txt\'))\n    return result\n\ndef customer_hash():\n    with sqlite3.connect(\'file:/etc/x-ui/x-ui.db?mode=ro\',uri=True) as db:\n        rows=db.execute(\'select id,tag,protocol,port,settings,stream_settings from inbounds order by id\').fetchall()\n        peers=db.execute(\'select id,email,wg_allowed_ips,enable,wg_public_key,wg_keep_alive from clients order by id\').fetchall()\n    return hashlib.sha256(repr((rows,peers)).encode()).hexdigest()\n\ndef service_state():return {n:output(\'systemctl\',\'show\',n,\'-p\',\'MainPID\',\'-p\',\'ActiveState\') for n in [\'x-ui\',\'amnezia-native32\',\'amnezia-legacy-kernel-guard\']}\n\nassert output(\'awg\',\'show\',\'xui-awg1\',\'peers\').strip(),\'Kernel AWG interface has no loaded peers\'\nexists=command([\'nft\',\'list\',\'table\',\'inet\',TABLE],False).returncode==0\nold_rules=json.loads(output(\'ip\',\'-j\',\'-4\',\'rule\'))\nwan_route=json.loads(output(\'ip\',\'-j\',\'-4\',\'route\',\'get\',\'1.1.1.1\'))[0]\nwan,gateway=wan_route[\'dev\'],wan_route[\'gateway\']\nassert re.fullmatch(\'[A-Za-z0-9_.:-]{1,15}\',wan) and not wan.startswith((\'lo\',\'wg\',\'awg\',\'xui\',\'tun\'))\nipaddress.IPv4Address(gateway)\nguard=json.loads(output(\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\'))\nif exists:\n    adoption=json.loads((root/\'adopt.json\').read_text())\n    assert adoption[\'wan\']==wan and adoption[\'gateway\']==gateway,\'WAN changed; disable old bypass first\'\n    verify_resources(adoption)\nelse:\n    assert not any(r.get(\'priority\') in PRIORITIES for r in old_rules),\'Policy priorities occupied\'\n    assert not command([\'ip\',\'-4\',\'route\',\'show\',\'table\',ROUTE_TABLE],False).stdout.strip(),\'Routing table occupied\'\n    assert not any(r.get(\'comment\',\'\').startswith(PREFIX) for r in rules(guard)),\'Stale bypass guard exceptions\'\nall_rules=rules(json.loads(output(\'nft\',\'-j\',\'list\',\'ruleset\')))\nfor rule in all_rules:\n    ours=exists and rule.get(\'family\')==\'inet\' and (rule.get(\'table\')==TABLE or (rule.get(\'table\')==\'amnezia_legacy_relay\' and rule.get(\'comment\',\'\').startswith(PREFIX)))\n    assert ours or \'"key": "mark"\' not in json.dumps(rule[\'expr\']),\'Unrelated packet/connection marking needs review\'\noriginal_guard=[r for r in rules(guard) if not r.get(\'comment\',\'\').startswith(PREFIX)]\ntg=command([\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'awg_tg_client31_trial\'],False)\ntg_signatures=[rule_signature(r) for r in rules(json.loads(tg.stdout))] if tg.returncode==0 else None\nbefore={\'customers\':customer_hash(),\'services\':service_state(),\'main_routes\':output(\'ip\',\'-4\',\'route\',\'show\',\'table\',\'main\'),\n \'guard\':[rule_signature(r) for r in original_guard],\'telegram_trial\':tg_signatures}\n(root/\'before.json\').write_text(json.dumps(before,indent=2))\n(root/\'guard-before.nft\').write_text(output(\'nft\',\'-a\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\'))\n(root/\'rules-before.json\').write_text(json.dumps(old_rules,indent=2))\nconfig=(nft_cleanup(guard,True) if exists else \'\')+nft_config(source[\'ipv4_cidrs\'],wan,anchor(guard))\npath=root/\'trial.nft\';path.write_text(config)\ncommand([\'nft\',\'-c\',\'-f\',str(path)])\nstamp=datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\')\nstate={\'version\':VERSION,\'mode\':\'all\',\'source_subnet\':SOURCE,\'wan\':wan,\'gateway\':gateway,\'table\':TABLE,\'route_table\':ROUTE_TABLE,\n \'mark\':MARK,\'mask\':MASK,\'timer\':\'awg-ru3-rollback-\'+stamp,\'rollback_deadline_utc\':(datetime.now(timezone.utc)+timedelta(minutes=30)).isoformat(),\n \'source_commit\':source[\'source_commit\'],\'source_sha256\':source[\'source_sha256\'],\'ipv4_cidrs\':len(networks),\n \'runtime_only\':True,\'new_connections_only\':True,\'new_clients_automatic\':True,\'migrated_existing_bypass\':exists}\n(root/\'state.json\').write_text(json.dumps(state,indent=2))\nrollback=root/\'rollback.py\'\nmanual=root/\'manual-rollback.sh\';manual.write_text(\'#!/bin/sh\\nset -eu\\n/usr/bin/python3 \'+str(rollback)+\'\\n\');manual.chmod(0o700)\ncommand([\'systemd-run\',\'--unit=\'+state[\'timer\'],\'--on-active=30m\',\'--timer-property=AccuracySec=1s\',\'/usr/bin/python3\',str(rollback)])\ntry:\n    if not exists:\n        for args in routing_commands(wan,gateway):command(args)\n    command([\'nft\',\'-f\',str(path)])\n    after_guard=rules(json.loads(output(\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\')))\n    assert len([r for r in after_guard if r.get(\'comment\',\'\').startswith(PREFIX)])==2\n    for original in before[\'guard\']:\n        matches=[r for r in after_guard if r[\'handle\']==original[\'handle\']]\n        assert len(matches)==1 and rule_signature(matches[0])==original,\'Original guard changed\'\n    if tg_signatures is not None:\n        assert [rule_signature(r) for r in rules(json.loads(output(\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'awg_tg_client31_trial\')))]==tg_signatures,\'Telegram MSS rules changed\'\n    checks=[]\n    for ip in [\'10.8.0.2\',\'10.8.0.127\',\'10.8.0.254\']:\n        for destination in [\'77.88.55.80\',\'1.1.1.1\',\'149.154.167.50\']:\n            direct=is_ru(destination)\n            result=output(\'ip\',\'-4\',\'route\',\'get\',destination,\'from\',ip,\'iif\',\'xui-awg1\',\'mark\',MARK if direct else \'0\')\n            expected=\'dev \'+wan+\' table \'+ROUTE_TABLE if direct else \'dev awg32 table 51832\'\n            assert expected in result,result\n            checks.append({\'source\':ip,\'destination\':destination,\'egress\':wan if direct else \'awg32\'})\n    assert customer_hash()==before[\'customers\'],\'Customer configuration changed\'\n    assert service_state()==before[\'services\'],\'Service state changed\'\n    assert output(\'ip\',\'-4\',\'route\',\'show\',\'table\',\'main\')==before[\'main_routes\'],\'Main routing changed\'\n    report={**state,\'installed_utc\':datetime.now(timezone.utc).isoformat(),\'customers_unchanged\':True,\'production_services_unchanged\':True,\n     \'original_guard_unchanged\':True,\'telegram_mss_trial_unchanged\':True,\'route_checks\':checks}\n    (root/\'verified.json\').write_text(json.dumps(report,indent=2))\n    verify_all(root,state)\n    print(json.dumps({k:v for k,v in report.items() if k!=\'route_checks\'}),flush=True)\nexcept BaseException:\n    result=subprocess.run([\'/usr/bin/python3\',str(rollback)],capture_output=True,text=True)\n    (root/\'apply-failure-rollback.txt\').write_text(result.stdout+result.stderr)\n    if result.returncode:raise RuntimeError(\'Apply failed and rollback needs review: \'+str(root))\n    raise\n', 'control.py': '"""on/off apply to every kernel AWG customer in SOURCE, including future peers."""\nimport argparse\nfrom datetime import datetime, timezone\nimport fcntl,json,os,shutil,subprocess\nfrom pathlib import Path\nfrom ru_bypass_common import TABLE,SOURCE,verify_all,verify_resources\n\nBASE=Path(__file__).resolve().parent\nPOINTER=BASE/\'controller-current.json\'\n\ndef run(*args,check=True):\n    r=subprocess.run(args,capture_output=True,text=True)\n    if check and r.returncode:raise RuntimeError(r.stderr.strip() or r.stdout.strip() or \'Command failed\')\n    return r\n\ndef current():\n    if POINTER.exists():\n        root=Path(json.loads(POINTER.read_text())[\'root\'])\n        assert root.parent==BASE/\'runs\',\'Invalid state path\'\n    elif (BASE/\'legacy.json\').exists():\n        root=Path(json.loads((BASE/\'legacy.json\').read_text())[\'root\'])\n        assert root.is_absolute() and str(root).startswith(\'/root/amnezia-relay-deploy/\') and root.resolve()==root,\'Invalid legacy path\'\n    else:return None,None\n    state=json.loads((root/\'state.json\').read_text())\n    assert state[\'table\']==TABLE,\'Unknown bypass table\'\n    return root,state\n\ndef active():return run(\'nft\',\'list\',\'table\',\'inet\',TABLE,check=False).returncode==0\n\ndef stop_timer(state):\n    if not state:return\n    timer=state[\'timer\']\n    assert timer.startswith(\'awg-ru3-rollback-\') and \'/\' not in timer\n    run(\'systemctl\',\'stop\',timer+\'.timer\',check=False)\n    if run(\'systemctl\',\'is-active\',timer+\'.service\',check=False).stdout.strip() in (\'active\',\'activating\',\'deactivating\'):\n        raise RuntimeError(\'Rollback is running. Wait a few seconds and retry.\')\n    assert run(\'systemctl\',\'is-active\',timer+\'.timer\',check=False).stdout.strip()!=\'active\',\'Could not stop rollback timer\'\n\ndef main():\n    parser=argparse.ArgumentParser(description=\'All AWG customers: Russian IPv4 direct bypass, runtime only.\')\n    parser.add_argument(\'action\',choices=[\'on\',\'off\',\'status\'])\n    args=parser.parse_args()\n    assert os.geteuid()==0,\'Run as root on the relay\'\n    os.umask(0o077)\n    with (BASE/\'controller.lock\').open(\'a\') as lock:\n        fcntl.flock(lock,fcntl.LOCK_EX)\n        root,state=current();enabled=active()\n        if enabled:\n            assert root and state,\'Unmanaged bypass exists; refusing to overwrite it\'\n            if state.get(\'mode\')==\'all\':verify_all(root,state)\n            else:verify_resources(state)\n        if args.action==\'status\':\n            if enabled and state.get(\'mode\')==\'all\':print(\'ON ALL: Russian IPv4 uses relay; other destinations use foreign exit.\')\n            elif enabled:print(\'LEGACY SELECTED MODE: old selected-peer trial is active; run ru-bypass on to switch ALL AWG customers.\')\n            else:print(\'OFF: all AWG destinations use the existing foreign exit.\')\n            print(\'on/off scope: ALL kernel AWG customers in \'+SOURCE+\'. Newly created peers in this subnet are automatic when ON.\')\n            timer=state and run(\'systemctl\',\'is-active\',state[\'timer\']+\'.timer\',check=False).stdout.strip()==\'active\'\n            print(\'Automatic rollback: \'+state[\'rollback_deadline_utc\'] if enabled and timer else \'No active automatic rollback timer.\')\n            print(\'Runtime only: reboot removes bypass. IPv4 only; domains/DNS and VLESS are unchanged.\')\n            return\n        stop_timer(state)\n        enabled=active()\n        if args.action==\'off\':\n            if state:print(run(\'/usr/bin/python3\',str(root/\'rollback.py\')).stdout.strip())\n            assert not active(),\'Bypass table remains after rollback\'\n            print(\'OFF for ALL AWG customers. Reconnect VPN/reopen apps to replace old connections.\')\n            return\n        if not enabled or state.get(\'mode\')!=\'all\':\n            newroot=BASE/\'runs\'/datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%S%fZ\')\n            newroot.mkdir(parents=True,mode=0o700)\n            for name in [\'ru_bypass_common.py\',\'apply.py\',\'rollback.py\',\'ru-ipv4.json\',\'simulation-report.json\']:\n                shutil.copyfile(BASE/name,newroot/name)\n            if enabled:\n                verify_resources(state)\n                (newroot/\'adopt.json\').write_text(json.dumps(state))\n            result=run(\'/usr/bin/python3\',str(newroot/\'apply.py\'),check=False)\n            (newroot/\'controller-apply.log\').write_text(result.stdout+result.stderr)\n            if result.returncode:raise RuntimeError(\'Enable failed; protected apply/rollback log: \'+str(newroot/\'controller-apply.log\'))\n            root=newroot;state=json.loads((root/\'state.json\').read_text())\n            tmp=POINTER.with_suffix(\'.tmp\');tmp.write_text(json.dumps({\'root\':str(root)}));tmp.replace(POINTER)\n        verify_all(root,state);stop_timer(state)\n        assert active() and not (root/\'rolled-back.json\').exists(),\'Rollback occurred; run on again\'\n        (root/\'manual-mode.json\').write_text(json.dumps({\'on_utc\':datetime.now(timezone.utc).isoformat(),\'automatic_expiry\':False}))\n        print(\'ON ALL AWG customers in \'+SOURCE+\'. New peers in this subnet automatically use this policy.\')\n        print(\'Russian IPv4: relay; other destinations: foreign exit. No automatic expiry. Reboot removes bypass.\')\n\nif __name__==\'__main__\':\n    try:main()\n    except (AssertionError,RuntimeError,OSError,ValueError) as error:raise SystemExit(\'ERROR: \'+str(error))\n', 'rollback.py': '"""Idempotently remove only the subnet-wide bypass, preserving other firewall/routing state."""\nimport json,subprocess,sys,time\nfrom pathlib import Path\nfrom ru_bypass_common import TABLE,nft_cleanup,cleanup_commands\n\nroot=Path(__file__).resolve().parent\nstate=json.loads((root/\'state.json\').read_text())\ndef run(args,check=False):\n    result=subprocess.run(args,capture_output=True,text=True)\n    if check and result.returncode:raise RuntimeError(result.stderr.strip() or \'Trial rollback command failed\')\n    return result\nguard=run([\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\'])\ndocument=json.loads(guard.stdout) if guard.returncode==0 else {\'nftables\':[]}\nexists=run([\'nft\',\'list\',\'table\',\'inet\',TABLE]).returncode==0\ntext=nft_cleanup(document,exists)\nif text:\n    path=root/\'rollback.nft\';path.write_text(text)\n    run([\'nft\',\'-c\',\'-f\',str(path)],check=True)\n    run([\'nft\',\'-f\',str(path)],check=True)\nfor command in cleanup_commands(state[\'wan\'],state[\'gateway\']):run(command)\n(root/\'rolled-back.json\').write_text(json.dumps({\'utc_epoch\':int(time.time()),\'removed_trial_only\':True},indent=2))\nprint(\'RU bypass removed. Original AWG routing restored; customer configuration and other trials retained.\')\n', 'simulate.py': '"""Exercise the exact nft/PBR/NAT rules in disposable namespaces, not production."""\nimport ipaddress,json,os,subprocess,sys,time,uuid\nfrom pathlib import Path\nfrom ru_bypass_common import TABLE,MARK,ROUTE_TABLE,anchor,nft_config,routing_commands,cleanup_commands,nft_cleanup\n\nTESTPEERS={\'fixtureA\':\'10.8.0.101\',\'fixtureB\':\'10.8.0.102\',\'fixtureC\':\'10.8.0.103\'}\nNEWPEER=\'10.8.0.104\'\nroot=Path(sys.argv[1]).resolve()\nsource=json.loads((root/\'ru-ipv4.json\').read_text())\ntag=\'rub\'+uuid.uuid4().hex[:7]\nnames={role:tag+role for role in [\'r\',\'c\',\'w\',\'f\']}\ncreated=[];links=[];servers=[]\ndef run(args,check=True):\n    result=subprocess.run(args,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)\n    if check and result.returncode:\n        detail=\'\\n\'.join(line[:350] for line in result.stderr.splitlines()[:15])\n        raise RuntimeError(\'Namespace command failed: \'+\' \'.join(args[:7])+\'\\n\'+detail)\n    return result\ndef ns(role,*args,check=True):return run([\'ip\',\'netns\',\'exec\',names[role],*args],check=check)\ndef link(a,b,iface_a,iface_b,number):\n    left=tag+\'a\'+str(number);right=tag+\'b\'+str(number)\n    run([\'ip\',\'link\',\'add\',left,\'type\',\'veth\',\'peer\',\'name\',right]);links.append(left)\n    run([\'ip\',\'link\',\'set\',left,\'netns\',names[a]])\n    run([\'ip\',\'link\',\'set\',right,\'netns\',names[b]])\n    ns(a,\'ip\',\'link\',\'set\',left,\'name\',iface_a);ns(b,\'ip\',\'link\',\'set\',right,\'name\',iface_b)\n    ns(a,\'ip\',\'link\',\'set\',iface_a,\'up\');ns(b,\'ip\',\'link\',\'set\',iface_b,\'up\')\ndef nft(role,text,name):\n    path=root/name;path.write_text(text)\n    ns(role,\'nft\',\'-c\',\'-f\',str(path));ns(role,\'nft\',\'-f\',str(path))\ntry:\n    existing=run([\'ip\',\'netns\',\'list\']).stdout\n    for name in names.values():\n        assert name not in existing\n        run([\'ip\',\'netns\',\'add\',name]);created.append(name)\n    for role in names:ns(role,\'ip\',\'link\',\'set\',\'lo\',\'up\')\n    link(\'r\',\'c\',\'xui-awg1\',\'client0\',1)\n    link(\'r\',\'w\',\'ens3\',\'sink0\',2)\n    link(\'r\',\'f\',\'awg32\',\'sink0\',3)\n    for role,interface,address in [(\'r\',\'xui-awg1\',\'10.8.0.1/24\'),(\'r\',\'ens3\',\'192.0.2.1/24\'),\n          (\'w\',\'sink0\',\'192.0.2.2/24\'),(\'r\',\'awg32\',\'10.203.32.2/30\'),(\'f\',\'sink0\',\'10.203.32.1/30\')]:\n        ns(role,\'ip\',\'address\',\'add\',address,\'dev\',interface)\n    for ip in TESTPEERS.values():ns(\'c\',\'ip\',\'address\',\'add\',ip+\'/24\',\'dev\',\'client0\')\n    ns(\'c\',\'ip\',\'route\',\'add\',\'default\',\'via\',\'10.8.0.1\')\n    ns(\'r\',\'sysctl\',\'-q\',\'-w\',\'net.ipv4.ip_forward=1\',\'net.ipv4.conf.all.rp_filter=0\',\'net.ipv4.conf.default.rp_filter=0\')\n    for iface in [\'ens3\',\'awg32\',\'xui-awg1\']:ns(\'r\',\'sysctl\',\'-q\',\'-w\',f\'net.ipv4.conf.{iface}.rp_filter=0\')\n    ns(\'r\',\'ip\',\'route\',\'add\',\'default\',\'via\',\'192.0.2.2\')\n    ns(\'r\',\'ip\',\'route\',\'add\',\'table\',\'51832\',\'default\',\'dev\',\'awg32\')\n    ns(\'r\',\'ip\',\'rule\',\'add\',\'priority\',\'10031\',\'from\',\'10.8.0.0/24\',\'table\',\'51832\')\n    ns(\'r\',\'ip\',\'rule\',\'add\',\'priority\',\'10032\',\'from\',\'10.8.0.0/24\',\'unreachable\')\n    base=\'\'\'table inet amnezia_legacy_relay {\n chain forward_guard {\n  type filter hook forward priority -10; policy accept;\n  iifname "xui-awg1" ip saddr != 10.8.0.0/24 drop\n  iifname "xui-awg1" ip daddr { 10.0.0.0/8, 127.0.0.0/8, 192.168.0.0/16 } drop\n  iifname "xui-awg1" oifname != "awg32" drop\n  oifname "xui-awg1" iifname != "awg32" drop\n  oifname "xui-awg1" ct state != { established, related } drop\n }\n chain old_nat { type nat hook postrouting priority srcnat - 1; policy accept;\n  ip saddr 10.8.0.0/24 oifname "awg32" snat ip to 10.203.32.2\n }\n}\n\'\'\'\n    nft(\'r\',base,\'sim-base.nft\')\n    for role,path_label in [(\'w\',\'relay-wan\'),(\'f\',\'foreign-exit\')]:\n        for ip in [\'77.88.55.80\',\'1.1.1.1\']:ns(role,\'ip\',\'address\',\'add\',ip+\'/32\',\'dev\',\'lo\')\n        code="from http.server import BaseHTTPRequestHandler,HTTPServer\\nimport json\\nclass H(BaseHTTPRequestHandler):\\n def do_GET(self):\\n  body=json.dumps({\'path\':"+repr(path_label)+",\'source_ip\':self.client_address[0]}).encode();self.send_response(200);self.end_headers();self.wfile.write(body)\\n def log_message(self,*args):pass\\nHTTPServer((\'0.0.0.0\',18080),H).serve_forever()"\n        servers.append(subprocess.Popen([\'ip\',\'netns\',\'exec\',names[role],\'python3\',\'-u\',\'-c\',code],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL))\n    time.sleep(.3)\n    guard=json.loads(ns(\'r\',\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\').stdout)\n    config=nft_config(source[\'ipv4_cidrs\'],\'ens3\',anchor(guard))\n    nft(\'r\',config,\'sim-trial.nft\')\n    for command in routing_commands(\'ens3\',\'192.0.2.2\'):ns(\'r\',*command)\n    # Add a new source only AFTER the bypass rules are loaded; no rule rebuild.\n    ns(\'c\',\'ip\',\'address\',\'add\',NEWPEER+\'/24\',\'dev\',\'client0\')\n    records=[]\n    def request(ip,destination,expected):\n        response=ns(\'c\',\'curl\',\'--noproxy\',\'*\',\'--interface\',ip,\'-fsS\',\'--connect-timeout\',\'2\',\'--max-time\',\'3\',f\'http://{destination}:18080\')\n        result=json.loads(response.stdout)\n        assert result[\'path\']==expected,(ip,destination,result)\n        assert result[\'source_ip\']==(\'192.0.2.1\' if expected==\'relay-wan\' else \'10.203.32.2\'),result\n        records.append({\'source\':ip,\'destination\':destination,\'path\':result[\'path\'],\'snat\':result[\'source_ip\']})\n    for ip in [*TESTPEERS.values(),NEWPEER]:\n        request(ip,\'77.88.55.80\',\'relay-wan\')\n        request(ip,\'1.1.1.1\',\'foreign-exit\')\n    ns(\'r\',\'ip\',\'route\',\'del\',\'table\',ROUTE_TABLE,\'default\',\'via\',\'192.0.2.2\',\'dev\',\'ens3\')\n    failed=ns(\'c\',\'curl\',\'--noproxy\',\'*\',\'--interface\',next(iter(TESTPEERS.values())),\'-fsS\',\'--max-time\',\'2\',\'http://77.88.55.80:18080\',check=False)\n    assert failed.returncode!=0,\'Marked route must fail closed if its table is unavailable\'\n    ns(\'r\',\'ip\',\'route\',\'add\',\'table\',ROUTE_TABLE,\'default\',\'via\',\'192.0.2.2\',\'dev\',\'ens3\')\n    guard=json.loads(ns(\'r\',\'nft\',\'-j\',\'list\',\'table\',\'inet\',\'amnezia_legacy_relay\').stdout)\n    nft(\'r\',nft_cleanup(guard,True),\'sim-rollback.nft\')\n    for command in cleanup_commands(\'ens3\',\'192.0.2.2\'):ns(\'r\',*command)\n    for ip in [*TESTPEERS.values(),NEWPEER]:\n        request(ip,\'77.88.55.80\',\'foreign-exit\')\n        request(ip,\'1.1.1.1\',\'foreign-exit\')\n    report={\'namespace_tests\':len(records),\'mode\':\'all\',\'all_awg_ru_direct\':True,\'new_peer_auto\':True,\n        \'non_ru_foreign\':True,\'snat_verified\':True,\'fail_closed_verified\':True,\'rollback_verified\':True,\n        \'production_network_untouched\':True,\'records\':records}\n    (root/\'simulation-report.json\').write_text(json.dumps(report,indent=2))\n    print(json.dumps({k:v for k,v in report.items() if k!=\'records\'}),flush=True)\nfinally:\n    for process in servers:\n        process.terminate()\n        try:process.wait(timeout=2)\n        except subprocess.TimeoutExpired:process.kill();process.wait()\n    for name in reversed(created):run([\'ip\',\'netns\',\'del\',name],check=False)\n    for name in links:run([\'ip\',\'link\',\'del\',name],check=False)\n'}
"""Single-file setup/upgrade; setup never enables subnet-wide bypass."""
import argparse,fcntl,hashlib,ipaddress,json,os,re,subprocess,urllib.request
from pathlib import Path

BASE=Path('/root/amnezia-relay-deploy/ru-bypass-all-v2')
COMMAND=Path('/usr/local/sbin/ru-bypass')
GEO_COMMIT='eace600e4e2d6708de3948b047ff9ff7bc5b5b11'
GEO_SHA='779e867ddeec1aca1e9501cc8cfe45f9c5d77531512a36c58d51e949da49adde'

def main():
    p=argparse.ArgumentParser(description='All-customer AWG IPv4 RU bypass. install enables; setup only updates the command.')
    p.add_argument('action',nargs='?',default='install',choices=['install','setup','on','off','status'])
    args=p.parse_args()
    assert os.geteuid()==0,'Run as root on the relay, not the exit'
    os.umask(0o077)
    wrapper='#!/bin/sh\nexec /usr/bin/python3 '+str(BASE/'control.py')+' "$@"\n'
    assert not COMMAND.is_symlink(),'Refusing to overwrite a symlink'
    existing=COMMAND.read_text() if COMMAND.exists() else None
    legacy=re.fullmatch(r'#!/bin/sh\nexec /usr/bin/python3 (/root/amnezia-relay-deploy/(?:ru-bypass3-[0-9TZ]+|ru-bypass)/control.py) "\$@"\n',existing or '')
    assert existing is None or existing==wrapper or legacy,'An unrelated ru-bypass command exists'
    if args.action in ('off','status') and existing:
        subprocess.run([str(COMMAND),args.action],check=True)
        return
    legacy_root=None
    if legacy:
        legacy_root=Path(legacy.group(1)).parent
        pointer=legacy_root/'controller-current.json'
        if pointer.exists():
            candidate=Path(json.loads(pointer.read_text())['root'])
            assert candidate.parent==legacy_root/'runs','Invalid old state pointer'
            legacy_root=candidate
        # The old portable installer might have been set up without an applied state.
        if not (legacy_root/'state.json').exists():legacy_root=None
    BASE.mkdir(parents=True,exist_ok=True,mode=0o700)
    with (BASE/'install.lock').open('a') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX)
        for name,content in FILES.items():
            assert not (BASE/name).exists() or (BASE/name).read_text()==content,'Installed code differs: '+name
            compile(content,name,'exec')
        if not (BASE/'ru-ipv4.json').exists():
            url=f'https://raw.githubusercontent.com/Loyalsoldier/geoip/{GEO_COMMIT}/text/ru.txt'
            request=urllib.request.Request(url,headers={'User-Agent':'awg-ru-bypass-all-v2'})
            with urllib.request.urlopen(request,timeout=45) as response:data=response.read(2*1024*1024)
            assert hashlib.sha256(data).hexdigest()==GEO_SHA,'GeoIP checksum mismatch'
            nets=[ipaddress.ip_network(line.strip(),strict=True) for line in data.decode().splitlines() if line.strip()]
            v4=list(ipaddress.collapse_addresses(n for n in nets if n.version==4))
            assert 1000<len(v4)<100000 and all(n.is_global and n.prefixlen>=8 for n in v4),'Unexpected country networks'
            (BASE/'ru-ipv4.json').write_text(json.dumps({'source_commit':GEO_COMMIT,'source_sha256':GEO_SHA,'ipv4_cidrs':[str(n) for n in v4]}))
        for name,content in FILES.items():(BASE/name).write_text(content)
        print('Checking all-customer routing, new-peer matching and rollback in isolated namespaces...',flush=True)
        subprocess.run(['/usr/bin/python3',str(BASE/'simulate.py'),str(BASE)],check=True)
        if legacy_root:(BASE/'legacy.json').write_text(json.dumps({'root':str(legacy_root)}))
        tmp=COMMAND.with_name('ru-bypass.new')
        assert not tmp.is_symlink(),'Refusing temporary command symlink'
        tmp.write_text(wrapper);tmp.chmod(0o700);tmp.replace(COMMAND)
    action='status' if args.action=='setup' else ('on' if args.action in ('install','on') else args.action)
    subprocess.run([str(COMMAND),action],check=True)
    print('Commands: ru-bypass on | ru-bypass off | ru-bypass status. on/off now cover ALL AWG customers.',flush=True)

if __name__=='__main__':
    try:main()
    except (AssertionError,RuntimeError,OSError,ValueError,subprocess.CalledProcessError) as error:raise SystemExit('ERROR: '+str(error))

RU_BYPASS_PYTHON
